/**
 * Builds the branded, per-game-type join broadcast baked into EssentialsX's
 * `custom-join-message` (see patchEssentialsJoinMessage below) — a short
 * Nxeon-branded welcome plus the 3 most useful commands for whatever game
 * type is actually active, sourced from that type's own `helpCommands`
 * (see FreeMcPreset's doc comment for how each list was verified). Uses
 * EssentialsX's own `&` colour-code convention and its `{PLAYER}` placeholder
 * — see https://essentialsx.net/wiki/Formatting.html and the placeholder list
 * in config.yml's `custom-join-message` comment block.
 */
export function buildFreemcWelcomeMessage(type: FreeMcGameType): string {
  const hints = (type.helpCommands ?? []).slice(0, 3);
  const tail = hints.length
    ? `Try ${hints.map((c) => `&f${c}&7`).join(", ")}.`
    : "Have fun!";
  return `&b[Nxeon]&f Welcome, {PLAYER}! &7This is a free &b${type.label}&7 server — ${tail}`;
}

/**
 * Patches EssentialsX's `custom-join-message` (config.yml) in place with a
 * given message — read-modify-write over the whole file rather than a `sed`
 * one-liner (unlike the IridiumSkyblock patch below) because the message
 * itself is full of `&` colour codes, which `sed`'s replacement syntax treats
 * as "insert the matched text" unless individually escaped — a real footgun
 * for a value built from data, not a fixed literal. Read+regex+writeback (via
 * execInput's stdin path, same mechanism as writeServerProperties) sidesteps
 * that whole class of shell/sed escaping bug entirely. Live-verified this
 * session: a config patched this way survives an immediate `docker restart`
 * (the same restart applyModeProperties always does right after this runs)
 * with no YAML parse errors and Essentials fully re-enabling.
 */
async function patchEssentialsJoinMessage(
  conn: Client,
  containerName: string,
  message: string,
): Promise<{ ok: boolean; error?: string }> {
  const path = "/data/plugins/Essentials/config.yml";
  const read = await dockerExec(conn, containerName, `cat ${path}`, 10_000);
  if (read.code !== 0) {
    return { ok: false, error: read.stderr.trim() || "Could not read Essentials config.yml" };
  }
  // YAML double-quoted scalar: only \ and " need escaping (our messages never
  // contain either today, but a future edit might).
  const yamlValue = message.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const patched = read.stdout.replace(/^custom-join-message:.*$/m, `custom-join-message: "${yamlValue}"`);
  if (patched === read.stdout) {
    return { ok: false, error: "custom-join-message key not found in Essentials config.yml" };
  }
  const write = await execInput(
    conn,
    `docker exec -i ${shellQuote(containerName)} sh -c ${shellQuote(`cat > ${path}`)}`,
    patched,
    10_000,
  );
  if (write.code !== 0) return { ok: false, error: write.stderr.trim() || "Could not write Essentials config.yml" };
  return { ok: true };
}

